import static org.junit.Assert.*;

/** Real native HTTP audio from an in-memory loopback fixture; no YouTube/account requests. */
public class BackgroundOnlineTest {
 private Instrumentation test;private Context context;private MainActivity activity;private TestMusicFixtures.Snapshot snapshot;private OnlineAudio.Resolver original,originalLegacy;private AudioServer server;private File offline;
 private final Track first=new Track("abcdefghijk","Online first","Fixture artist",40,true,""),second=new Track("12345678901","Online second","Fixture artist",40,true,"");
 private void main(Runnable run){test.runOnMainSync(run);}
 private void await(java.util.function.BooleanSupplier ready)throws Exception{long end=System.currentTimeMillis()+12000;while(!ready.getAsBoolean()&&System.currentTimeMillis()<end)Thread.sleep(80);assertTrue("Condition timed out",ready.getAsBoolean());}
 @Before public void setup()throws Exception{test=InstrumentationRegistry.getInstrumentation();context=test.getTargetContext();snapshot=new TestMusicFixtures.Snapshot(context);original=LocalPlayerService.onlineResolver;originalLegacy=LocalPlayerService.legacyResolver;main(()->context.stopService(new Intent(context,LocalPlayerService.class)));await(()->LocalPlayerService.active==null);SleepTimer.set(context,0);context.getSharedPreferences("music",0).edit().putInt("volume",0).remove("playerError").commit();TestMusicFixtures.seed(context,List.of(first,second));if(Build.VERSION.SDK_INT>=33)test.getUiAutomation().grantRuntimePermission(context.getPackageName(),android.Manifest.permission.POST_NOTIFICATIONS);shell("input keyevent 224");shell("wm dismiss-keyguard");server=new AudioServer();LocalPlayerService.onlineResolver=(c,t,p)->new OnlineAudio.Source(server.url(),Map.of());activity=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));}
 @After public void cleanup()throws Exception{shell("input keyevent 224");main(()->{context.stopService(new Intent(context,LocalPlayerService.class));if(activity!=null)activity.finish();});await(()->LocalPlayerService.active==null);LocalPlayerService.onlineResolver=original;LocalPlayerService.legacyResolver=originalLegacy;if(server!=null)server.close();if(offline!=null)offline.delete();test.waitForIdleSync();snapshot.restore();}
 private void call(String name,Class<?>[] types,Object... values){main(()->{try{Method method=MainActivity.class.getDeclaredMethod(name,types);method.setAccessible(true);method.invoke(activity,values);}catch(Exception e){throw new AssertionError(e);}});}
 private boolean visible(){try{Field field=MainActivity.class.getDeclaredField("visible");field.setAccessible(true);return field.getBoolean(activity);}catch(Exception e){throw new AssertionError(e);}}
 private void play(){call("playTrack",new Class<?>[]{Track.class,List.class},first,List.of(first,second));}
 private void home(){context.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 private void shell(String command)throws Exception{try(ParcelFileDescriptor fd=test.getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){in.readAllBytes();}}
 @Test public void failedFastStreamFallsBackOnceWithoutLosingPausedState()throws Exception{
  AtomicInteger attempts=new AtomicInteger();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);
  LocalPlayerService.onlineResolver=(c,t,p)->new OnlineAudio.Source("http://127.0.0.1:1/unavailable",Map.of(),true);
  LocalPlayerService.legacyResolver=(c,t,p)->{attempts.incrementAndGet();entered.countDown();if(!release.await(10,TimeUnit.SECONDS))throw new IOException("Fixture timeout");return new OnlineAudio.Source(server.url(),Map.of());};
  play();assertTrue(entered.await(10,TimeUnit.SECONDS));LocalPlayerService player=LocalPlayerService.active;main(player::pause);home();release.countDown();Thread.sleep(1500);assertFalse(player.playing());assertEquals("paused",player.state);main(player::play);await(player::playing);assertEquals(1,attempts.get());
 }
 @Test public void startsAfterHomeAndContinuesScreenOffWithMediaControls()throws Exception{
  Set<String> saved=new HashSet<>();for(File f:MusicRepository.files(context))saved.add(f.getName());CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);LocalPlayerService.onlineResolver=(c,t,p)->{entered.countDown();if(!release.await(15,TimeUnit.SECONDS))throw new IOException("Fixture timeout");return new OnlineAudio.Source(server.url(),Map.of());};play();assertTrue("Resolver did not start",entered.await(10,TimeUnit.SECONDS));home();await(()->!visible());release.countDown();await(()->LocalPlayerService.active!=null&&LocalPlayerService.active.playing());LocalPlayerService player=LocalPlayerService.active;assertTrue("Not using the online queue",player.online);assertTrue("Not using network playback",player.networkPlayback);assertEquals("",player.path);await(()->player.position()>250);int before=player.position();Thread.sleep(1300);assertTrue("Online position did not advance after Home: "+before+" -> "+player.position()+" / "+player.state,player.position()>before+600);shell("input keyevent 223");before=player.position();Thread.sleep(1400);assertTrue("Online audio stopped with screen off",player.position()>before+600);
  MediaController controller=new MediaController(context,player.sessionToken());assertEquals(first.title,controller.getMetadata().getString(android.media.MediaMetadata.METADATA_KEY_TITLE));assertEquals(PlaybackState.STATE_PLAYING,controller.getPlaybackState().getState());assertTrue(context.getSystemService(NotificationManager.class).getActiveNotifications().length>0);
  controller.getTransportControls().pause();await(()->!player.playing());controller.getTransportControls().seekTo(8000);await(()->Math.abs(player.position()-8000)<500);int paused=player.position();Thread.sleep(400);assertTrue(Math.abs(player.position()-paused)<150);controller.getTransportControls().play();await(player::playing);
  controller.getTransportControls().skipToNext();await(()->player.playing()&&player.song.id.equals(second.id));main(()->new MusicWidget().onReceive(context,new Intent(context,MusicWidget.class).setAction("com.pocketmusic.widget.previous")));await(()->player.playing()&&player.song.id.equals(first.id));assertTrue(server.requests.get()>0);Set<String> after=new HashSet<>();for(File f:MusicRepository.files(context))after.add(f.getName());assertEquals("Streaming created a saved music file",saved,after);
 }
 @Test public void pauseWhileResolvingNeverAutoplaysAndLocalSwitchCancelsStream()throws Exception{
  CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);LocalPlayerService.onlineResolver=(c,t,p)->{entered.countDown();release.await(15,TimeUnit.SECONDS);return new OnlineAudio.Source(server.url(),Map.of());};play();assertTrue("Resolver did not start",entered.await(10,TimeUnit.SECONDS));LocalPlayerService player=LocalPlayerService.active;main(player::pause);home();await(()->!visible());release.countDown();Thread.sleep(1200);assertFalse(player.playing());assertEquals("paused",player.state);main(player::play);await(player::playing);
  offline=new File(MusicRepository.folder(context),"Background switch fixture.wav");try(FileOutputStream out=new FileOutputStream(offline)){out.write(server.audio);}File chosen=offline;main(()->context.startForegroundService(new Intent(context,LocalPlayerService.class).putExtra("path",chosen.getAbsolutePath())));await(()->player.playing()&&!player.online);assertEquals(offline.getAbsolutePath(),player.path);assertFalse(player.networkPlayback);
 }
 @Test public void rapidNextRejectsStaleResolvedAudioAndTimerWorksInBackground()throws Exception{
  CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);LocalPlayerService.onlineResolver=(c,t,p)->{if(t.id.equals(first.id)){entered.countDown();while(release.getCount()>0)try{release.await(3,TimeUnit.SECONDS);}catch(InterruptedException ignored){}}return new OnlineAudio.Source(server.url(),Map.of());};play();assertTrue("Resolver did not start",entered.await(10,TimeUnit.SECONDS));LocalPlayerService player=LocalPlayerService.active;main(player::next);release.countDown();await(()->player.playing()&&player.song.id.equals(second.id));assertEquals(second.title,player.title);home();await(()->!visible());main(()->SleepTimer.set(context,500));await(()->!player.playing());int paused=player.position();Thread.sleep(500);assertTrue(Math.abs(player.position()-paused)<200);
 }
 @Test public void resolverFailureStopsForegroundSessionAndReportsUsefulError()throws Exception{LocalPlayerService.onlineResolver=(c,t,p)->{throw new IOException("Network unavailable");};play();await(()->LocalPlayerService.active==null&&context.getSharedPreferences("music",0).getString("playerError","").contains("Online audio unavailable"));assertTrue(context.getSharedPreferences("music",0).getString("playerError","").contains("Online audio unavailable"));}
 private static final class AudioServer implements AutoCloseable {
  final byte[] audio;final AtomicInteger requests=new AtomicInteger();private final ServerSocket socket;private volatile boolean closed;
  AudioServer()throws Exception{int samples=22050*40;ByteBuffer b=ByteBuffer.allocate(44+samples*2).order(ByteOrder.LITTLE_ENDIAN);b.put("RIFF".getBytes(StandardCharsets.US_ASCII)).putInt(36+samples*2).put("WAVEfmt ".getBytes(StandardCharsets.US_ASCII)).putInt(16).putShort((short)1).putShort((short)1).putInt(22050).putInt(44100).putShort((short)2).putShort((short)16).put("data".getBytes(StandardCharsets.US_ASCII)).putInt(samples*2);audio=b.array();socket=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));Thread accept=new Thread(()->{while(!closed)try{Socket client=socket.accept();Thread worker=new Thread(()->serve(client));worker.setDaemon(true);worker.start();}catch(IOException e){if(!closed)throw new RuntimeException(e);}});accept.setDaemon(true);accept.start();}
  String url(){return "http://127.0.0.1:"+socket.getLocalPort()+"/audio.wav";}
  private void serve(Socket client){try(Socket c=client){c.setSoTimeout(5000);BufferedReader in=new BufferedReader(new InputStreamReader(c.getInputStream(),StandardCharsets.US_ASCII));String first=in.readLine();if(first==null)return;int start=0;for(int lines=0;lines<64;lines++){String line=in.readLine();if(line==null||line.isEmpty())break;if(line.toLowerCase(Locale.ROOT).startsWith("range: bytes=")){String n=line.substring(line.indexOf('=')+1).split("-",2)[0];start=Integer.parseInt(n);}}start=Math.min(Math.max(start,0),audio.length-1);requests.incrementAndGet();OutputStream out=c.getOutputStream();String header="HTTP/1.1 "+(start>0?"206 Partial Content":"200 OK")+"\r\nContent-Type: audio/wav\r\nAccept-Ranges: bytes\r\nContent-Length: "+(audio.length-start)+"\r\n"+(start>0?"Content-Range: bytes "+start+"-"+(audio.length-1)+"/"+audio.length+"\r\n":"")+"Connection: close\r\n\r\n";out.write(header.getBytes(StandardCharsets.US_ASCII));if(!first.startsWith("HEAD"))out.write(audio,start,audio.length-start);out.flush();}catch(Exception ignored){}}
  public void close()throws IOException{closed=true;socket.close();}
 }
}
